# RW2DM_ARRAYCRV: ArrayCrv: copies along a curve by count or by distance. The script is rw2dm_arraycrv_script.txt; generated by rw2dm_gen.py (the closed forms are in that file). Every object kind of the case (Point, Line, Plane, Box) is
# compared with the closed-form image of the operation: points by the residual move to the origin (printed 0,0,0 within 1e-9), curve / surface control points
# through ExtractPt the same way, boxes by their bounding box after a residual move. RW2DM_ARRAYCRV_sensitivity shows that a 1e-6 error would read 1e-06.
RW2_ARRAYCRV_OUT=""
rw2_arraycrv_run() {
  local o
  if [ -n "${DISPLAY:-}" ] && xset q >/dev/null 2>&1 || ! command -v xvfb-run >/dev/null 2>&1; then
    o="$(timeout 900 "$BIN" --smoke 60 --script "$HERE/$1" 2>&1)" || { echo "$o" | tail -40; echo "FAIL RW2DM_ARRAYCRV_run: $1 exited non-zero"; fail=1; o=""; }
  else
    o="$(timeout 900 xvfb-run -a -s "-screen 0 1600x900x24" "$BIN" --smoke 60 --script "$HERE/$1" 2>&1)" || { echo "$o" | tail -40; echo "FAIL RW2DM_ARRAYCRV_run: $1 exited non-zero"; fail=1; o=""; }
  fi
  RW2_ARRAYCRV_OUT+="$o"$'\n'
}
rw2_arraycrv_run rw2dm_arraycrv_script.txt
rw2_arraycrv_block() { awk -v name="$1" '$0 ~ ("Unknown command: RW2BEGIN_" name "$") { on = 1; next } on && /Unknown command: RW2BEGIN_/ { exit } on { print }' <<<"$RW2_ARRAYCRV_OUT"; }
# rw2_arraycrv_resid NAME NPTS BOXES DESC: the case listed exactly NPTS points, every one at residual 0,0,0, and the boxes' bounding boxes (joined by ';') read exactly BOXES
rw2_arraycrv_resid() {
  local blk npts zeros boxes; blk="$(rw2_arraycrv_block "$1")"
  npts="$({ grep -cE '^history: Object [0-9]+ \(point\)' <<<"$blk" || true; })"
  zeros="$({ grep -cE '^history:   0,0,0$' <<<"$blk" || true; })"
  boxes="$({ grep -E '^history: Bounding box min ' <<<"$blk" || true; } | sed -E 's/^history: Bounding box //' | paste -sd';' -)"
  if [ "$npts" = "$2" ] && [ "$zeros" = "$2" ] && [ "$boxes" = "$3" ]; then echo "ok   RW2DM_ARRAYCRV_$1: $4 ($2 points at residual 0 within 1e-9; boxes: ${3:-none})"
  else echo "FAIL RW2DM_ARRAYCRV_$1: $4 (listed $npts points, $zeros at residual 0, expected $2 and $2; boxes '$boxes', expected '$3')"; fail=1; { grep -E '^history:   |^history: Bounding box|^history: ! ' <<<"$blk" || true; } | head -16 | sed 's/^/     residual: /'; fi
}
rw2_arraycrv_resid count 51 "min 0,0,0 max 2,2,2;min 0,0,0 max 2,2,2;min 0,0,0 max 2,2,2;min 0,0,0 max 2,2,2;min 0,0,0 max 2,2,2;min 0,0,0 max 2,2,2;min 0,0,0 max 2,2,2" "ArrayCrv with 6 items on the straight path (0,0,0)-(6,8,0): stations every 2 units of arc length (i * 2 * (0.6,0.8)), i = 0..5; copy 0 sits on the original (point, line, plane, box)"
rw2_arraycrv_resid free 51 "min 0,0,0 max 2,2,2;min 0,0,0 max 2,2,2;min 0,0,0 max 2,2,2;min 0,0,0 max 2,2,2;min 0,0,0 max 2,2,2;min 0,0,0 max 2,2,2;min 0,0,0 max 2,2,2" "ArrayCrv with the default Freeform orientation on a straight path: the frames do not turn along a line, so the copies are the same translations"
rw2_arraycrv_resid distance 37 "min 0,0,0 max 2,2,2;min 0,0,0 max 2,2,2;min 0,0,0 max 2,2,2;min 0,0,0 max 2,2,2;min 0,0,0 max 2,2,2" "ArrayCrv Distance=3 on the path of length 10: stations at 0, 3, 6 and 9 (a multiple of the distance each, none at the end 10)"
rw2_arraycrv_resid distexact 30 "min 0,0,0 max 2,2,2;min 0,0,0 max 2,2,2;min 0,0,0 max 2,2,2;min 0,0,0 max 2,2,2" "ArrayCrv Distance=5 on the path of length 10: an exact multiple, so stations at 0, 5 and 10 (the end is included)"
# negative control: the same harness must SEE a 1e-6 error (a point 1e-6 off its expected image reads 1e-06, not 0)
rw2_arraycrv_sens() {
  local blk; blk="$(rw2_arraycrv_block sensitivity)"
  if grep -qE '^history:   (0,0,)?[-0-9.e]*1e-06' <<<"$blk" && ! grep -qE '^history:   0,0,0$' <<<"$blk"; then echo "ok   RW2DM_ARRAYCRV_sensitivity: the residual harness reports a 1e-6 error as 1e-06 (negative control)"
  else echo "FAIL RW2DM_ARRAYCRV_sensitivity: a 1e-6 error was not visible"; fail=1; { grep -E '^history:   ' <<<"$blk" || true; } | head -4 | sed 's/^/     residual: /'; fi
}
rw2_arraycrv_sens
